import React, { useState } from 'react';
import { useOSStore } from '../store/useOSStore';
import { INITIAL_EMAILS, INITIAL_SHADOWCHAT_FEED } from '../data/commsData';
import { Plus, Smile, Send, Paperclip, Mail, Scroll, Users, MessageSquare } from 'lucide-react';

export default function CommsApp() {
  const [activeView, setActiveView] = useState('chat'); // 'chat' | 'inbox'
  const [activeContact, setActiveContact] = useState('Aelita');
  const [selectedMail, setSelectedMail] = useState(null);
  const [composing, setComposing] = useState(false);
  const [composeRecipient, setComposeRecipient] = useState('Aelita');
  const [composeSubject, setComposeSubject] = useState('');
  const [composeBody, setComposeBody] = useState('');

  const addCredits = useOSStore((s) => s.addCredits);
  const addXP = useOSStore((s) => s.addXP);
  const advanceStarterPhase = useOSStore((s) => s.advanceStarterPhase);

  // Initial Data
  const [emails, setEmails] = useState(INITIAL_EMAILS);
  const [chatFeed, setChatFeed] = useState(INITIAL_SHADOWCHAT_FEED);
  const [chatInput, setChatInput] = useState('');

  // Contacts list matching Section 5C Cast
  const contacts = ['Aelita', 'Dr. Voss', 'Odd', 'Yumi', 'Jeremie', 'Ulrich', 'Sissi', 'Nerya'];

  const claimAttachment = (mailId) => {
    setEmails((prev) =>
      prev.map((m) => {
        if (m.id === mailId && m.attachment && !m.attachment.claimed) {
          addCredits(m.attachment.amount);
          addXP(m.attachment.amount / 2);
          advanceStarterPhase();
          useOSStore.getState().addSkillXP('Communication', 25);
          useOSStore.getState().addSkillXP('Networking', 25);
          const updatedMail = { ...m, attachment: { ...m.attachment, claimed: true } };
          setSelectedMail(updatedMail);
          return updatedMail;
        }
        return m;
      })
    );
  };

  const handleSendChat = (e) => {
    if ((e.key === 'Enter' || e.type === 'click') && chatInput.trim()) {
      setChatFeed((prev) => [
        ...prev,
        { id: Date.now(), user: 'You (Operative)', team: activeContact, text: chatInput.trim(), time: 'Just now' },
      ]);
      setChatInput('');
      useOSStore.getState().addSkillXP('Communication', 10);
    }
  };

  const handleSendCompose = () => {
    if (!composeSubject.trim() || !composeBody.trim()) return;
    setEmails((prev) => [
      {
        id: `SENT-${Date.now().toString().slice(-4)}`,
        sender: `To: ${composeRecipient}`,
        faction: 'Sent Transmission',
        subject: composeSubject,
        time: 'Just now',
        read: true,
        attachment: null,
        body: composeBody,
      },
      ...prev,
    ]);
    setComposing(false);
    setComposeSubject('');
    setComposeBody('');
  };

  const unreadCount = emails.filter((e) => !e.read && !e.id.startsWith('SENT')).length;

  return (
    <div className="flex flex-col h-full w-full bg-[#1C4B46] text-white font-sans text-xs select-none border-4 border-slate-900 overflow-hidden shadow-2xl">
      {/* ------------------------------------------------------------------ */}
      {/* TOP HEADER BANNER (MATCHING WIREFRAME: game communication)         */}
      {/* ------------------------------------------------------------------ */}
      <div className="h-11 bg-[#2C6961] border-b-4 border-slate-900 flex items-center px-4 shrink-0">
        <h1 className="font-mono text-xl font-black text-emerald-100 tracking-wider lowercase">
          game communication
        </h1>
      </div>

      {/* ------------------------------------------------------------------ */}
      {/* MAIN CONTENT AREA: LEFT SIDEBAR + RIGHT CHAT PANEL                 */}
      {/* ------------------------------------------------------------------ */}
      <div className="flex flex-1 overflow-hidden">
        {/* LEFT SIDEBAR (CONTACT STACK + SCROLL + MAIL ENVELOPE) */}
        <div className="w-52 bg-[#2C6961] border-r-4 border-slate-900 p-3 flex flex-col justify-between shrink-0">
          {/* Top Section: Stacked Contacts */}
          <div className="space-y-2 overflow-y-auto max-h-[220px] pr-1">
            {contacts.map((contact) => (
              <button
                key={contact}
                onClick={() => {
                  setActiveContact(contact);
                  setActiveView('chat');
                }}
                className={`w-full py-1.5 px-3 rounded-lg border-2 border-slate-900 text-left font-mono font-bold text-xs transition shadow ${
                  activeContact === contact && activeView === 'chat'
                    ? 'bg-[#61B5A9] text-slate-950 shadow-md translate-x-1'
                    : 'bg-[#3B8276] text-white hover:bg-[#489A8D]'
                }`}
              >
                CONTACT: {contact}
              </button>
            ))}
          </div>

          {/* Middle Section: Scroll / Quill Compose Icon */}
          <div className="flex flex-col items-center py-2">
            <button
              onClick={() => setComposing(true)}
              className="p-3 rounded-2xl bg-amber-100 border-2 border-slate-900 hover:bg-amber-200 transition shadow-md group relative"
              title="Compose New Scroll / Transmission"
            >
              <span className="text-2xl">📜</span>
              <span className="absolute -bottom-5 text-[9px] font-mono font-bold text-amber-200 opacity-0 group-hover:opacity-100 transition">
                Scroll
              </span>
            </button>
          </div>

          {/* Bottom Section: Mail Envelope Icon with Unread Counter */}
          <div className="flex flex-col items-center pt-2 border-t-2 border-slate-900/40">
            <button
              onClick={() => setActiveView('inbox')}
              className={`p-3 rounded-2xl border-2 border-slate-900 transition shadow-md relative group ${
                activeView === 'inbox' ? 'bg-purple-400 text-slate-950' : 'bg-purple-500 hover:bg-purple-400 text-white'
              }`}
              title="System Mailbox"
            >
              <Mail size={24} />
              {unreadCount > 0 && (
                <span className="absolute -top-1 -right-1 bg-red-500 text-white font-bold text-[10px] h-5 w-5 rounded-full flex items-center justify-center border border-slate-900 shadow">
                  {unreadCount}
                </span>
              )}
            </button>
          </div>
        </div>

        {/* RIGHT MAIN PANEL (CHAT / TRANSMISSION VIEW) */}
        <div className="flex-1 flex flex-col justify-between bg-[#4EA296] p-4 relative overflow-hidden">
          {activeView === 'chat' && (
            <div className="flex-1 flex flex-col justify-between h-full space-y-3">
              {/* Central Group/Chat Header & Icon Display */}
              <div className="flex items-center justify-between border-b-2 border-slate-900/40 pb-2">
                <div className="flex items-center gap-2 font-mono font-bold text-sm text-slate-950">
                  <MessageSquare size={18} className="text-slate-900" />
                  <span>Channel: {activeContact}</span>
                </div>
                <span className="bg-emerald-900/40 px-2 py-0.5 rounded text-[10px] font-mono text-emerald-100 border border-slate-900">
                  SECURE MESH
                </span>
              </div>

              {/* Chat Message Feed */}
              <div className="flex-1 overflow-y-auto space-y-3 bg-[#3B8276]/60 rounded-2xl p-4 border-2 border-slate-900 shadow-inner">
                {/* Central Chat Illustration Banner matching wireframe */}
                <div className="flex flex-col items-center justify-center py-4 text-center text-slate-950">
                  <div className="p-4 rounded-full bg-white/30 border-2 border-slate-900 mb-2">
                    <Users size={40} className="text-slate-900" />
                  </div>
                  <span className="font-mono font-bold text-xs">Direct Transmission with {activeContact}</span>
                </div>

                {chatFeed.map((msg) => (
                  <div
                    key={msg.id}
                    className={`p-3 rounded-xl border-2 border-slate-900 shadow-sm max-w-[80%] ${
                      msg.user.startsWith('You')
                        ? 'bg-emerald-200 text-slate-950 ml-auto'
                        : 'bg-white text-slate-900 mr-auto'
                    }`}
                  >
                    <div className="flex justify-between items-center text-[10px] font-mono font-bold mb-1 border-b border-slate-900/20 pb-0.5">
                      <span>{msg.user}</span>
                      <span className="opacity-60">{msg.time}</span>
                    </div>
                    <div className="text-xs font-sans font-medium">{msg.text}</div>
                  </div>
                ))}
              </div>

              {/* ------------------------------------------------------------------ */}
              {/* BOTTOM INPUT BAR (MATCHING WIREFRAME: + INPUT 🙂)                  */}
              {/* ------------------------------------------------------------------ */}
              <div className="h-12 bg-slate-200 rounded-xl border-2 border-slate-900 flex items-center px-3 gap-2 shadow-md shrink-0">
                <button
                  onClick={() => alert('📎 Attachment menu opened!')}
                  className="p-1.5 rounded-lg bg-slate-300 hover:bg-slate-400 text-slate-900 font-bold text-lg border border-slate-500"
                  title="Add Attachment"
                >
                  <Plus size={18} />
                </button>

                <input
                  type="text"
                  value={chatInput}
                  onChange={(e) => setChatInput(e.target.value)}
                  onKeyDown={handleSendChat}
                  placeholder={`Send message to ${activeContact}...`}
                  className="flex-1 bg-transparent text-xs text-slate-900 outline-none font-sans font-medium placeholder-slate-500"
                />

                <button
                  onClick={handleSendChat}
                  className="p-1.5 rounded-lg bg-emerald-400 hover:bg-emerald-500 text-slate-950 font-bold border border-slate-900 transition"
                  title="Send Message"
                >
                  <Smile size={18} />
                </button>
              </div>
            </div>
          )}

          {activeView === 'inbox' && (
            <div className="flex-1 flex gap-3 h-full overflow-hidden">
              {/* Email List */}
              <div className="w-64 bg-[#3B8276]/60 rounded-xl border-2 border-slate-900 p-2 overflow-y-auto space-y-1.5">
                <div className="text-[10px] font-mono font-bold text-slate-950 uppercase px-1">
                  Official Transmissions ({emails.length})
                </div>
                {emails.map((m) => (
                  <div
                    key={m.id}
                    onClick={() => {
                      setSelectedMail(m);
                      setEmails((prev) => prev.map((e) => (e.id === m.id ? { ...e, read: true } : e)));
                    }}
                    className={`cursor-pointer rounded-lg border-2 p-2.5 transition ${
                      selectedMail?.id === m.id
                        ? 'border-slate-900 bg-emerald-300 text-slate-950 font-bold'
                        : m.read
                        ? 'border-slate-900/40 bg-white/70 text-slate-800'
                        : 'border-slate-900 bg-white text-slate-900 font-bold'
                    }`}
                  >
                    <div className="flex justify-between text-[10px]">
                      <span className="font-bold truncate">{m.sender}</span>
                      <span className="opacity-60">{m.time}</span>
                    </div>
                    <div className="text-xs truncate">{m.subject}</div>
                  </div>
                ))}
              </div>

              {/* Selected Email Panel */}
              <div className="flex-1 bg-white/90 rounded-xl border-2 border-slate-900 p-4 text-slate-900 overflow-y-auto flex flex-col justify-between">
                {selectedMail ? (
                  <div className="space-y-3">
                    <div className="border-b-2 border-slate-900/20 pb-2">
                      <h2 className="text-sm font-bold text-slate-950">{selectedMail.subject}</h2>
                      <div className="text-[10px] text-slate-600">From: {selectedMail.sender}</div>
                    </div>

                    {selectedMail.attachment && (
                      <div className="rounded-lg border-2 border-slate-900 bg-emerald-100 p-2.5 flex justify-between items-center">
                        <div>
                          <div className="font-bold text-emerald-950 text-xs">{selectedMail.attachment.name}</div>
                          <div className="text-[10px] text-emerald-800">Value: ₡{selectedMail.attachment.amount} Credits</div>
                        </div>
                        <button
                          onClick={() => claimAttachment(selectedMail.id)}
                          disabled={selectedMail.attachment.claimed}
                          className={`px-3 py-1 rounded-lg border-2 border-slate-900 font-bold text-xs ${
                            selectedMail.attachment.claimed ? 'bg-slate-300 text-slate-600' : 'bg-emerald-400 hover:bg-emerald-500 text-slate-950'
                          }`}
                        >
                          {selectedMail.attachment.claimed ? 'Claimed' : 'Claim'}
                        </button>
                      </div>
                    )}

                    <div className="font-mono text-xs whitespace-pre-wrap leading-relaxed">
                      {selectedMail.body}
                    </div>
                  </div>
                ) : (
                  <div className="flex h-full items-center justify-center font-mono text-slate-500 text-xs">
                    Select an official transmission from the list to view.
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* COMPOSE MODAL */}
      {composing && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm">
          <div className="w-96 rounded-2xl border-4 border-slate-900 bg-[#2C6961] p-4 text-white space-y-3 shadow-2xl">
            <div className="flex justify-between border-b-2 border-slate-900 pb-2 font-mono font-bold">
              <span>Compose Transmission</span>
              <button onClick={() => setComposing(false)} className="hover:text-red-300">✕</button>
            </div>

            <div className="space-y-2 text-xs">
              <div>
                <label className="text-[10px] block font-mono">Recipient:</label>
                <select
                  value={composeRecipient}
                  onChange={(e) => setComposeRecipient(e.target.value)}
                  className="w-full rounded-lg border-2 border-slate-900 bg-white text-slate-900 p-1.5 outline-none font-bold"
                >
                  {contacts.map((c) => (
                    <option key={c}>{c}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className="text-[10px] block font-mono">Subject:</label>
                <input
                  type="text"
                  value={composeSubject}
                  onChange={(e) => setComposeSubject(e.target.value)}
                  placeholder="Subject line..."
                  className="w-full rounded-lg border-2 border-slate-900 bg-white text-slate-900 p-1.5 outline-none font-bold"
                />
              </div>

              <div>
                <label className="text-[10px] block font-mono">Message:</label>
                <textarea
                  rows={4}
                  value={composeBody}
                  onChange={(e) => setComposeBody(e.target.value)}
                  placeholder="Write message..."
                  className="w-full rounded-lg border-2 border-slate-900 bg-white text-slate-900 p-1.5 outline-none font-medium resize-none"
                />
              </div>
            </div>

            <div className="flex justify-end gap-2 pt-1">
              <button
                onClick={() => setComposing(false)}
                className="px-3 py-1.5 rounded-lg border-2 border-slate-900 bg-slate-300 text-slate-900 font-bold hover:bg-slate-400"
              >
                Cancel
              </button>
              <button
                onClick={handleSendCompose}
                className="px-4 py-1.5 rounded-lg border-2 border-slate-900 bg-emerald-400 text-slate-950 font-bold hover:bg-emerald-500"
              >
                Send Scroll
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
